 const onL=AE_sw(xl,72,118,1,RED)+AE_sw(xl,192,238,1,RED)+AE_T(xl-24,100,'S1',{fs:22,fw:800,a:'end',fill:RED})+AE_T(xl-24,220,'S2',{fs:22,fw:800,a:'end',fill:RED});
 const ty=[350,420],gx=[110,300,340,560];
 const tim=AE_T(20,ty[0]+6,'S1',{fs:22,fw:700})+AE_T(20,ty[1]+6,'S2',{fs:22,fw:700})+AE_pl([[70,ty[0]+20],[gx[0],ty[0]+20],[gx[0],ty[0]-14],[gx[1],ty[0]-14],[gx[1],ty[0]+20],[590,ty[0]+20]],BLU,3)+AE_pl([[70,ty[1]+20],[gx[2],ty[1]+20],[gx[2],ty[1]-14],[gx[3],ty[1]-14],[gx[3],ty[1]+20],[590,ty[1]+20]],BLU,3)
